    "PENTE_PLAT_DEG": { "valeur": 3, "unite": "degres", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Et en deca de cette pente : l'ecoulement d'une toiture-terrasse, pas un pan.", "cas": ["vesinet/AE103"] },
