    "TOLERANCE_APPENTIS": { "valeur": 1.1, "unite": "rapport", "ou": "facade/toits/toitCorps.ts", "pourquoi": "L'appentis l'emporte sur un faux petit pan tant que son ecart ne depasse pas le sien de plus de 10 % (et TOLERANCE_APPENTIS_M).", "cas": [] },
    "TOLERANCE_APPENTIS_M": { "valeur": 0.05, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le terme absolu de TOLERANCE_APPENTIS : une tolerance relative seule echoue sur des mesures parfaites.", "cas": [] },
