    "DECALAGE_MAX_M": { "valeur": 3, "unite": "m", "ou": "facade/toits/toitCorps.ts", "pourquoi": "Le plus grand decalage essaye, dans chaque sens, pour recaler un batiment.", "cas": ["vesinet/AE103"] },
